import{_ as a,o as e,c as d,a6 as s}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"从图像到短片分镜","description":"","frontmatter":{"id":"storyboard","title":"从图像到短片分镜","chapter":"10","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":36,"content_kind":"任务入门"},"headers":[],"relativePath":"video/storyboard.md","filePath":"video/storyboard.md"}'),r={name:"video/storyboard.md"};function o(n,t,i,l,p,h){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="从图像到短片-先做可拍的三镜头分镜" tabindex="-1">从图像到短片，先做可拍的三镜头分镜 <a class="header-anchor" href="#从图像到短片-先做可拍的三镜头分镜" aria-label="Permalink to &quot;从图像到短片，先做可拍的三镜头分镜&quot;">​</a></h1><p>本节以收纳盒使用过程为练习，写出镜头表、关键帧任务与剪辑顺序。先有真实商品和动作依据，再做关键帧。图片好看不能证明视频里商品、手部和动作稳定。</p><h2 id="_1-先写镜头-不先写-大气宣传片" tabindex="-1">1. 先写镜头，不先写“大气宣传片” <a class="header-anchor" href="#_1-先写镜头-不先写-大气宣传片" aria-label="Permalink to &quot;1. 先写镜头，不先写“大气宣传片”&quot;">​</a></h2><table tabindex="0"><thead><tr><th>镜头</th><th>可见动作</th><th>素材与检查</th></tr></thead><tbody><tr><td>01</td><td>书桌上的盒子，手准备开盖</td><td>完整商品，盖子结构正确</td></tr><tr><td>02</td><td>把文具放进盒子</td><td>真实容量与隔板，手不穿模</td></tr><tr><td>03</td><td>合盖，桌面变简洁</td><td>同一商品、位置与文具</td></tr></tbody></table><p>是否适用这些动作按真实商品确认。没有能放下的文具实拍，就不要用视频暗示大容量。时长按具体平台与内容调整，本节不承诺固定秒数能提高转化。</p><h2 id="_2-给助手一份完整分镜任务" tabindex="-1">2. 给助手一份完整分镜任务 <a class="header-anchor" href="#_2-给助手一份完整分镜任务" aria-label="Permalink to &quot;2. 给助手一份完整分镜任务&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据商品实拍、使用说明和三镜头动作表，整理一条收纳盒使用短片的分镜。每镜输出构图、动作起点与终点、必要道具、字幕、声音需求和关键帧素材。</span></span>
<span class="line"><span>保持同一商品、颜色、盖子和隔板结构，不增加功能、配件、性能数字或虚构用户评价。动作必须由说明或实拍支持。缺真实动作素材时列补拍项，不把生成关键帧当作视频成功结果。</span></span>
<span class="line"><span>字幕为独立准确文案，关键帧不生成文字。给出镜头连接时要核对的商品位置、手部关系和道具连续性。</span></span></code></pre></div><h2 id="_3-再做关键帧与视频" tabindex="-1">3. 再做关键帧与视频 <a class="header-anchor" href="#_3-再做关键帧与视频" aria-label="Permalink to &quot;3. 再做关键帧与视频&quot;">​</a></h2><p>关键帧用真实商品和相同背景，通过商品核对后才交给图生视频工具。每镜只要求一个明确动作，避免同时开盖、旋转、换颜色和变换机位。生成后完整观看，逐帧查接触关系、物体数量和结构，不只挑一个好看的截图。</p><p>剪辑时按动作连接，加准确字幕与合适声音，重新连续播放检查节奏和信息。输出原镜头、剪辑工程状态、成片与未完成项。完整模板<a href="./../prompts/P07">P07</a>，本项目尚未生成或连续审看片。</p>`,10)])])}const b=a(r,[["render",o]]);export{_ as __pageData,b as default};
